const STATES = {
  'quicklaunch': {
    url: b => b,
    setup: async page => {
      await page.waitForSelector('ul li a[href]', { state: 'visible', timeout: 15000 });
      await page.waitForTimeout(1000); // hydratation React : le keydown global n'existe qu'après mount
      await page.keyboard.type('home');
      await page.waitForSelector('dialog input', { state: 'visible', timeout: 15000 });
      // fondu d'entrée de la modale (opacity 0→1, 300ms) : on mesure l'état
      // stabilisé perçu par l'utilisateur, pas une frame intermédiaire
      await page.waitForTimeout(400);
    },
  },
  'dark-theme': {
    url: b => b,
    setup: async page => {
      const btn = page.locator('button:has([class*="moon" i]), button[aria-label*="theme" i], button[title*="theme" i]').first();
      if (await btn.count()) { await btn.click(); await page.waitForTimeout(800); }
      else { await page.evaluate(() => document.documentElement.classList.add('dark')); }
    },
  },
};
